const closeList = () => { if (listType) { html.push('</' + listType + '>'); listType = null; } };
const splitRow = (line) => line.trim().replace(/^\|/, '').replace(/\|$/, '').split('|').map((x) => x.trim());

for (let i = 0; i < lines.length; i++) {
  const line = lines[i];
  if (!line.trim()) { flushPara(); closeList(); continue; }

  const h = line.match(/^(#{1,4})\s+(.*)$/);
  if (h) { flushPara(); closeList(); html.push('<h' + h[1].length + dirAttr + '>' + inline(h[2]) + '</h' + h[1].length + '>'); continue; }

  if (/^\s*([-*_])\1{2,}\s*$/.test(line)) { flushPara(); closeList(); html.push('<hr>'); continue; }

  if (/^\s*\|/.test(line)) {
    flushPara(); closeList();
    const rows = [];
    while (i < lines.length && /^\s*\|/.test(lines[i])) { rows.push(lines[i]); i++; }
    i--;
